6: package {PACKAGE_NAME};
7: 
8: // Overview
9: //
10: // ONNX is an open specification that is comprised of the following components:
11: //
12: // 1)  A definition of an extensible computation graph model.
13: // 2)  Definitions of standard data types.
14: // 3)  Definitions of built-in operators.
15: //
16: // This document describes the syntax of models and their computation graphs,
17: // as well as the standard data types. Together, they are referred to as the ONNX
18: // Intermediate Representation, or 'IR' for short.
19: //
20: // The normative semantic specification of the ONNX IR is found in docs/IR.md.
21: // Definitions of the built-in neural network operators may be found in docs/Operators.md.
22: // #if ONNX-ML
23: // Definitions of the built-in classical machine learning operators may be found in
24: // docs/Operators-ml.md.
25: // #endif
26: 
27: // Notes
28: //
29: // Protobuf compatibility
30: //
31: // To simplify framework compatibility, ONNX is defined using the subset of protobuf
32: // that is compatible with both protobuf v2 and v3. This means that we do not use any
33: // protobuf features that are only available in one of the two versions.
34: //
35: // Here are the most notable contortions we have to carry out to work around
36: // these limitations:
37: //
38: //   - No 'map' (added protobuf 3.0). We instead represent mappings as lists
39: //     of key-value pairs, where order does not matter and duplicates
40: //     are not allowed.
41: 
42: 
43: // Versioning
44: //
45: // ONNX versioning is specified in docs/IR.md and elaborated on in docs/Versioning.md
46: //
47: // To be compatible with both proto2 and proto3, we will use a version number
48: // that is not defined by the default value but an explicit enum number.
49: enum Version {
50:   // proto3 requires the first enum value to be zero.
51:   // We add this just to appease the compiler.
52:   _START_VERSION = 0;
53:   // The version field is always serialized and we will use it to store the
54:   // version that the  graph is generated from. This helps us set up version
55:   // control.
56:   // For the IR, we are using simple numbers starting with 0x00000001,
57:   // which was the version we published on Oct 10, 2017.
58:   IR_VERSION_2017_10_10 = 0x0000000000000001;
59: 
60:   // IR_VERSION 2 published on Oct 30, 2017
61:   // - Added type discriminator to AttributeProto to support proto3 users
62:   IR_VERSION_2017_10_30 = 0x0000000000000002;
63: 
64:   // IR VERSION 3 published on Nov 3, 2017
65:   // - For operator versioning:
66:   //    - Added new message OperatorSetIdProto
67:   //    - Added opset_import in ModelProto
68:   // - For vendor extensions, added domain in NodeProto
69:   IR_VERSION_2017_11_3 = 0x0000000000000003;
70: 
71:   // IR VERSION 4 published on Jan 22, 2019
72:   // - Relax constraint that initializers should be a subset of graph inputs
73:   // - Add type BFLOAT16
74:   IR_VERSION_2019_1_22 = 0x0000000000000004;
75: 
76:   // IR VERSION 5 published on March 18, 2019
77:   // - Add message TensorAnnotation.
78:   // - Add quantization annotation in GraphProto to map tensor with its scale and zero point quantization parameters.
79:   IR_VERSION_2019_3_18 = 0x0000000000000005;
