41: // Generic type caster template for ONNX Proto classes
42: #define ONNX_DEFINE_TYPE_CASTER(ProtoType, PythonClassName)                                       \
43:   template <>                                                                                     \
44:   struct nanobind::detail::type_caster<ONNX_NAMESPACE::ProtoType> {                               \
45:    public:                                                                                        \
46:     NB_TYPE_CASTER(ONNX_NAMESPACE::ProtoType, nanobind::detail::const_name(PythonClassName));     \
47:                                                                                                   \
48:     bool from_python(handle py_proto, uint8_t, cleanup_list*) noexcept {                          \
49:       try {                                                                                       \
50:         if (!nanobind::hasattr(py_proto, "SerializeToString")) {                                  \
51:           return false;                                                                           \
52:         }                                                                                         \
53:         auto serialized = nanobind::cast<nanobind::bytes>(py_proto.attr("SerializeToString")());  \
54:         return ParseProtoFromPyBytes(&value, serialized);                                         \
55:       } catch (...) {                                                                             \
56:         /* from_python is noexcept: nanobind::cast (cast_error) and ParseProtoFromPyBytes      */ \
57:         /* (bad_alloc) can throw non-python_error types, which would otherwise call terminate. */ \
58:         return false;                                                                             \
59:       }                                                                                           \
60:     }                                                                                             \
61:                                                                                                   \
62:     static handle from_cpp(                                                                       \
63:         const ONNX_NAMESPACE::ProtoType& cpp_proto,                                               \
64:         rv_policy /* policy */,                                                                   \
65:         cleanup_list* /* cleanup */) noexcept {                                                   \
66:       try {                                                                                       \
67:         std::string serialized = cpp_proto.SerializeAsString();                                   \
68:         auto py_proto = nanobind::module_::import_("onnx").attr(#ProtoType)();                    \
69:         py_proto.attr("ParseFromString")(nanobind::bytes(serialized.c_str(), serialized.size())); \
70:         return py_proto.release();                                                                \
71:       } catch (...) {                                                                             \
72:         return handle();                                                                          \
73:       }                                                                                           \
74:     }                                                                                             \
75:   };
