92: // Serialize a proto message into Python bytes.
93: static nb::bytes ProtoToBytes(const BASE_PROTO_TYPE& proto) {
94:   std::string out = proto.SerializeAsString();
95:   return nb::bytes(out.data(), out.size());
96: }
