98: // Parse a vector of Python bytes into a vector of protos.
99: template <typename ProtoType>
100: static std::vector<ProtoType> ParseProtoVector(const std::vector<nb::bytes>& bytes_vec) {
101:   std::vector<ProtoType> protos(bytes_vec.size());
102:   for (size_t i = 0; i < bytes_vec.size(); ++i) {
103:     ParseProtoFromPyBytes(&protos[i], bytes_vec[i]);
104:   }
105:   return protos;
106: }
