114: template <typename ProtoType>
115: static std::tuple<bool, nb::bytes, nb::bytes> Parse(const char* cstr) {
116:   ProtoType proto{};
117:   OnnxParser parser(cstr);
118:   auto status = parser.Parse(proto);
119:   const std::string& error_msg = status.ErrorMessage();
120:   return std::make_tuple(status.IsOK(), nb::bytes(error_msg.c_str(), error_msg.size()), ProtoToBytes(proto));
121: }
