130: template <typename T, typename Ts = std::remove_const_t<T>>
131: static std::pair<std::vector<Ts>, std::unordered_map<std::string, T*>> ParseProtoFromBytesMap(
132:     const std::unordered_map<std::string, nb::bytes>& bytesMap) {
133:   std::vector<Ts> values(bytesMap.size());
134:   std::unordered_map<std::string, T*> result;
135:   size_t i = 0;
136:   for (const auto& [key, bytes] : bytesMap) {
137:     ParseProtoFromPyBytes(&values[i], bytes);
138:     result[key] = &values[i];
139:     i++;
140:   }
141:   // C++ guarantees that the pointers remain valid after std::vector<Ts> is moved.
142:   return std::make_pair(std::move(values), result);
143: }
