145: static std::unordered_map<std::string, nb::bytes> CallNodeInferenceFunction(
146:     OpSchema* schema,
147:     const nb::bytes& nodeBytes,
148:     const std::unordered_map<std::string, nb::bytes>& valueTypesByNameBytes,
149:     const std::unordered_map<std::string, nb::bytes>& inputDataByNameBytes,
150:     const std::unordered_map<std::string, nb::bytes>& inputSparseDataByNameBytes,
151:     std::unordered_map<std::string, int> opsetImports,
152:     const int irVersion) {
153:   NodeProto node{};
154:   ParseProtoFromPyBytes(&node, nodeBytes);
155:   // Early fail if node is badly defined - may throw ValidationError
156:   schema->Verify(node);
157: 
158:   // Convert arguments to C++ types, allocating memory
159:   const auto& valueTypes = ParseProtoFromBytesMap<TypeProto>(valueTypesByNameBytes);
160:   const auto& inputData = ParseProtoFromBytesMap<const TensorProto>(inputDataByNameBytes);
161:   const auto& inputSparseData = ParseProtoFromBytesMap<const SparseTensorProto>(inputSparseDataByNameBytes);
162:   if (opsetImports.empty()) {
163:     opsetImports[schema->domain()] = schema->SinceVersion();
164:   }
165: 
166:   shape_inference::GraphInferenceContext graphInferenceContext(
167:       valueTypes.second, opsetImports, nullptr, {}, OpSchemaRegistry::Instance(), nullptr, irVersion);
168:   // Construct inference context and get results - may throw InferenceError
169:   // TODO(ONNX): if it is desirable for infer_node_outputs to provide check_type, strict_mode, data_prop,
170:   // we can add them to the Python API. For now we just assume the default options.
171:   ShapeInferenceOptions options{false, 0, false};
172:   shape_inference::InferenceContextImpl ctx(
173:       node, valueTypes.second, inputData.second, inputSparseData.second, options, nullptr, &graphInferenceContext);
174:   schema->GetTypeAndShapeInferenceFunction()(ctx);
175:   // Verify the inference succeeded - may also throw ValidationError
176:   // Note that input types were not validated until now (except that their count was correct)
177:   schema->CheckInputOutputType(ctx);
178: 
179:   // Convert back into bytes returned to Python
180:   std::unordered_map<std::string, nb::bytes> typeProtoBytes;
181:   for (size_t i = 0; i < ctx.allOutputTypes_.size(); i++) {
182:     const auto& proto = ctx.allOutputTypes_[i];
183:     if (proto.IsInitialized()) {
184:       typeProtoBytes[node.output(static_cast<int>(i))] = ProtoToBytes(proto);
185:     }
186:   }
187: 
188:   return typeProtoBytes;
189: }
