191: template <typename T>
192: static std::tuple<std::vector<T>, std::vector<const T*>> ConvertPyObjToPtr(const std::vector<nb::object>& pyObjs) {
193:   std::vector<T> objs;
194:   std::vector<const T*> ptrs;
195:   objs.reserve(pyObjs.size());
196:   ptrs.reserve(pyObjs.size());
197:   for (const auto& obj : pyObjs) {
198:     if (obj.is_none()) {
199:       ptrs.push_back(nullptr);
200:       continue;
201:     }
202:     objs.emplace_back(nanobind::cast<T>(obj));
203:     ptrs.push_back(&objs.back());
204:   }
205:   return std::make_tuple(std::move(objs), std::move(ptrs));
206: }
