208: // Build a binding that parses a proto from Python bytes and runs the given
209: // checker function on it. The proto type and the trailing context arguments
210: // are deduced from the checker's signature, so this covers both the 2-arg
211: // (CheckerContext) and 3-arg (CheckerContext + LexicalScopeContext) checkers.
212: template <typename ProtoType, typename... Ctx>
213: static auto MakeChecker(void (*check_fn)(const ProtoType&, const Ctx&...)) {
214:   return [check_fn](const nb::bytes& bytes, const Ctx&... ctx) {
215:     ProtoType proto{};
216:     ParseProtoFromPyBytes(&proto, bytes);
217:     check_fn(proto, ctx...);
218:   };
219: }
